def contents_of(path) -> Dict:
    entries = {}
    for entry in os.scandir(path):
        if entry.is_symlink():
            # Symlinks are special, and generally not allowed
            entries[entry.name] = Symlink
        elif entry.is_dir():
            entries[entry.name] = Directory
        elif entry.is_file():
            entries[entry.name] = File
        else:
            # This is always a sign of an error
            entries[entry.name] = Unknown
    return entries


def scan_structure(path, structure=ALLOWED_STRUCTURE):
    errors = []
    entries = contents_of(path)

    existing = set(entries.keys())
    valid = set(structure.keys())

    # Unknown types are errors
    unknown = set(
        [name for name, entry_type in entries.items() if entry_type is Unknown]
    )
    for unk in unknown:
        errors.append(f"Unknown:   {path}/{unk}")

    # Extraneous entries are errors
    for invalid in existing.difference(valid):
        errors.append(f"Forbidden: {path}/{invalid}")

    # Missing entries are errors, unless entry is optional
    required = set(
        [
            name
            for name, entry_type in structure.items()
            if entry_type not in (OptionalFile, OptionalDirectory)
        ]
    )
    for missing in required.difference(existing):
        errors.append(f"Missing:   {path}/{missing}")

    # Bad type of existing entry constitutes an error
    for name, entry_type in entries.items():
        if name not in structure:
            # Already checked this above
            continue

        expected_type = structure[name]
        if isinstance(expected_type, dict) or expected_type is OptionalDirectory:
            expected_type = Directory
        elif expected_type is OptionalFile:
            expected_type = File

        if entry_type is not expected_type:
            errors.append(
                f"Bad type:  {path}/{name} - should be {expected_type.__name__}"
            )

    # Recurse into next level of the structure
    recurse_to = {
        name: substructure
        for name, substructure in structure.items()
        if (
            isinstance(substructure, dict)
            and name in existing
            and entries[name] is Directory
        )
    }
    for name, substructure in recurse_to.items():
        next_path = path + "/" + name
        errors.extend(scan_structure(next_path, substructure))

    return errors


if __name__ == "__main__":
    assert len(sys.argv) == 2, "Second argument should be a path to main suite"
    testsuite_path = sys.argv[1]

    errors = scan_structure(testsuite_path)

    if errors:
        print(WARNING_MESSAGE)
        print("Errors:")
        print("\n".join(errors))
        sys.exit(1)

    print("All good.")
